import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Color, PointLight, Mesh, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'quote-panel-journal';

  const timelines = [];
  const disposables = [];

  // ---- Card geometry / material ----
  const cardW = 2.4;
  const cardH = 1.5;
  const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.55,
    metalness: 0.3,
    side: DoubleSide,
  });
  cardMat.clearcoat = 0.15;
  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0;
  root.add(card);
  disposables.push(cardGeo, cardMat);

  // ---- Accent edge frame (focus / hover indicator) ----
  const edgeGeo = new PlaneGeometry(cardW + 0.08, cardH + 0.08, 1, 1);
  const edgeOpacity = uniform(0.0);
  const edgeMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
  });
  edgeMat.colorNode = mix(vec3(0.0, 0.0, 0.0), vec3(1.0, 0.165, 0.22), 1.0);
  edgeMat.opacityNode = edgeOpacity;
  edgeMat.color = new Color(colors.accent);
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.01;
  root.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // ---- Contact shadow (subtle grounding) ----
  const shadowGeo = new PlaneGeometry(cardW * 1.3, cardH * 1.3, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.35,
    side: DoubleSide,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.06, -0.05);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Local rim light for card readability (accent hued) ----
  const rimLight = new PointLight(new Color(colors.accent), 0.7, 4.0);
  rimLight.position.set(-1.2, 0.6, 1.4);
  root.add(rimLight);

  // ---- Texture load (async, ctx loader only) ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- Idle breathing (weight, single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(root.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(idleTl);

  // ---- Hover: rise-in preset (subtle 0.15 units) + accent edge focus ----
  const baseY = 0;
  const hoverState = { edge: 0 };
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(root.position, {
    y: baseY + 0.15,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  hoverTl.to(hoverState, {
    edge: 1,
    duration: 0.3,
    ease: 'power2.out',
    onUpdate: () => {
      edgeOpacity.value = hoverState.edge * 0.85;
    },
  }, 0);
  timelines.push(hoverTl);

  // ---- Click: press-down + emit navigation event ----
  const clickTl = gsap.timeline({ paused: true });
  clickTl.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(2)',
    yoyo: true,
    repeat: 1,
  });
  timelines.push(clickTl);

  root.userData.handlers = {
    onPointerOver: () => {
      hoverTl.play();
    },
    onPointerOut: () => {
      hoverTl.reverse();
    },
    onPointerDown: () => {
      clickTl.restart();
    },
    onClick: () => {
      ctx.emit('hub-journal.select', { nodeId: config.id ?? 'hub-journal-quote' });
    },
  };

  // ---- Cinematic primitive: parallax-scroll ----
  const primitiveResults = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    if (typeof ctx.primitives?.[prim.name] === 'function') {
      const params = { ...(prim.params ?? {}), trigger: prim.trigger ?? 'scroll' };
      const result = ctx.primitives[prim.name](root, params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const r of primitiveResults) {
      r?.cleanup?.();
    }
    for (const d of disposables) {
      d?.dispose?.();
    }
    if (cardMat.map) {
      cardMat.map.dispose?.();
    }
    root.remove(rimLight);
  };

  return root;
}
